operation.add:
// Factura electronica EN 16931 (modulo eInvoicing): autoinstalacion idempotente
try {
	$this->load->model('einvoicing/einvoicing');
	$this->model_einvoicing_einvoicing->install();

	$einvoicing_group = $this->db->query("SELECT permission FROM `" . DB_PREFIX . "user_group` WHERE user_group_id = 1");

	if ($einvoicing_group->num_rows) {
		$einvoicing_perm = unserialize($einvoicing_group->row['permission']);

		if (is_array($einvoicing_perm) && isset($einvoicing_perm['access']) && isset($einvoicing_perm['modify'])) {
			$einvoicing_perm_changed = false;

			foreach (array('access', 'modify') as $einvoicing_type) {
				if (!in_array('einvoicing/einvoicing', $einvoicing_perm[$einvoicing_type])) {
					$einvoicing_perm[$einvoicing_type][] = 'einvoicing/einvoicing';
					$einvoicing_perm_changed = true;
				}
			}

			if ($einvoicing_perm_changed) {
				$this->db->query("UPDATE `" . DB_PREFIX . "user_group` SET permission = '" . $this->db->escape(serialize($einvoicing_perm)) . "' WHERE user_group_id = 1");
			}
		}
	}
} catch (Exception $einvoicing_install_exception) {
	// No interrumpir la carga del admin; se reintenta en la siguiente carga.
}

if ($this->user->hasPermission('access', 'einvoicing/einvoicing')) {
	$sales[] = array(
		'name' => $this->language->get('text_einvoicing'),
		'href' => $this->url->link('einvoicing/einvoicing', 'token=' . $this->session->data['token'], 'SSL'),
		'children' => array()
	);
}

// Factura electronica EN 16931 (modulo eInvoicing): pestana de la ficha
$this->load->model('einvoicing/einvoicing');

$this->data['einvoicing_tab_einvoicing'] = $this->model_einvoicing_einvoicing->label('tab_einvoicing');
$this->data['einvoicing_text_info_generated'] = $this->model_einvoicing_einvoicing->label('text_info_generated');
$this->data['einvoicing_text_info_status'] = $this->model_einvoicing_einvoicing->label('text_info_status');
$this->data['einvoicing_text_info_profile'] = $this->model_einvoicing_einvoicing->label('text_info_profile');
$this->data['einvoicing_text_info_notice'] = $this->model_einvoicing_einvoicing->label('text_info_notice');
$this->data['einvoicing_button_regenerate_invoice'] = $this->model_einvoicing_einvoicing->label('button_regenerate_invoice');
$this->data['einvoicing_button_download_xml'] = $this->model_einvoicing_einvoicing->label('button_download_xml');

$einvoicing_info = $this->model_einvoicing_einvoicing->getInfo($invoice_id);

$this->data['einvoicing_generated'] = $einvoicing_info['generated'];
$this->data['einvoicing_status'] = $einvoicing_info['status'];
$this->data['einvoicing_profile'] = $einvoicing_info['profile'];
$this->data['einvoicing_notice'] = $einvoicing_info['valid'] ? '' : nl2br(htmlspecialchars($einvoicing_info['notice'], ENT_QUOTES, 'UTF-8'));
$this->data['einvoicing_has_xml'] = $einvoicing_info['has_xml'];
$this->data['einvoicing_xml'] = $this->url->link('einvoicing/einvoicing/xml', 'token=' . $this->session->data['token'] . '&invoice_id=' . (int)$invoice_id, 'SSL');
